create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,phone text,role text not null default 'owner' check(role in ('owner','admin')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.plans(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,price_monthly numeric(12,2) not null default 0,features jsonb not null default '{}'::jsonb,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.businesses(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,slug text unique not null,name text not null,logo_url text,description text,phone text,whatsapp text,address text,city text,maps_url text,opening_hours jsonb not null default '{}'::jsonb,plan_id uuid references public.plans(id),subscription_status text not null default 'free',is_published boolean not null default false,is_suspended boolean not null default false,is_featured boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.items(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,description text,price numeric(12,2),image_url text,type text not null default 'product' check(type in ('product','service')),is_active boolean not null default true,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.leads(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,phone text not null,email text,message text,status text not null default 'new' check(status in ('new','contacted','won','lost')),source text,created_at timestamptz not null default now());
create table if not exists public.analytics_events(id bigint generated always as identity primary key,business_id uuid not null references public.businesses(id) on delete cascade,event_type text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.subscriptions(id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,plan_id uuid not null references public.plans(id),provider text,external_id text,status text not null default 'active',starts_at timestamptz,ends_at timestamptz,created_at timestamptz not null default now());
create index if not exists businesses_owner_idx on public.businesses(owner_id);create index if not exists businesses_slug_idx on public.businesses(slug);create index if not exists items_business_idx on public.items(business_id,is_active);create index if not exists leads_business_idx on public.leads(business_id,created_at desc);create index if not exists analytics_business_idx on public.analytics_events(business_id,created_at desc);
insert into public.plans(name,slug,price_monthly,features) values('Free','free',0,'{"catalogue":true}'),('Starter','starter',199,'{"catalogue":true,"leads":true,"analytics":true}'),('Pro','pro',499,'{"catalogue":true,"leads":true,"analytics":true,"featured":true}') on conflict(slug) do nothing;
alter table public.profiles enable row level security;alter table public.plans enable row level security;alter table public.businesses enable row level security;alter table public.items enable row level security;alter table public.leads enable row level security;alter table public.analytics_events enable row level security;alter table public.subscriptions enable row level security;
create policy "profile owner" on public.profiles for select to authenticated using ((select auth.uid())=id);
create policy "public businesses" on public.businesses for select to anon using (is_published and not is_suspended);
create policy "business owner" on public.businesses for all to authenticated using ((select auth.uid())=owner_id) with check ((select auth.uid())=owner_id);
create policy "public items" on public.items for select to anon using (is_active and exists(select 1 from public.businesses b where b.id=business_id and b.is_published and not b.is_suspended));
create policy "item owner" on public.items for all to authenticated using (exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=(select auth.uid()))) with check (exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=(select auth.uid())));
create policy "lead owner" on public.leads for select to authenticated using (exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=(select auth.uid())));
create policy "analytics owner" on public.analytics_events for select to authenticated using (exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=(select auth.uid())));
create policy "public plans" on public.plans for select to anon using (is_active);
create policy "subscription owner" on public.subscriptions for select to authenticated using (exists(select 1 from public.businesses b where b.id=business_id and b.owner_id=(select auth.uid())));
create or replace function public.handle_new_user() returns trigger language plpgsql security invoker set search_path=public as $$begin insert into public.profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'name') on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();